package com.aiintelligence.event;

import com.aiintelligence.ai.*;
import com.aiintelligence.article.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ArticleProcessingService {
    private final ArticleService articles;private final EventService events;private final AiClient ai;private final PromptCatalog prompts;private final ObjectMapper mapper;private final PipelineRepository repository;private final double threshold,dvW,impactW,techW,availabilityW,credibilityW,freshnessW;
    public ArticleProcessingService(ArticleService articles,EventService events,AiClient ai,PromptCatalog prompts,ObjectMapper mapper,PipelineRepository repository,@Value("${ai.match-confidence-threshold:0.85}")double threshold,@Value("${ai.score-weights.developer-value:0.30}")double dvW,@Value("${ai.score-weights.impact:0.20}")double impactW,@Value("${ai.score-weights.technical:0.15}")double techW,@Value("${ai.score-weights.availability:0.15}")double availabilityW,@Value("${ai.score-weights.credibility:0.15}")double credibilityW,@Value("${ai.score-weights.freshness:0.05}")double freshnessW){this.articles=articles;this.events=events;this.ai=ai;this.prompts=prompts;this.mapper=mapper;this.repository=repository;this.threshold=threshold;this.dvW=dvW;this.impactW=impactW;this.techW=techW;this.availabilityW=availabilityW;this.credibilityW=credibilityW;this.freshnessW=freshnessW;}
    public Event process(long articleId,boolean force){Article a=articles.findById(articleId);Event linked=events.findByArticleId(articleId);if(!force&&linked!=null)return linked;articles.updateStatus(articleId,ArticleStatus.PROCESSING);try{if(a.title==null||a.title.trim().isEmpty()||a.cleanContent==null||a.cleanContent.length()<40){articles.updateStatus(articleId,ArticleStatus.IGNORED);return null;}JsonNode analysis=call("ARTICLE_ANALYSIS",articleId,null,prompts.articleAnalysis(),articleJson(a));validateAnalysis(analysis);if(!analysis.path("relevant").asBoolean()){articles.updateStatus(articleId,ArticleStatus.IGNORED);return null;}Event event=linked==null?matchOrCreate(a,analysis):linked;attach(event.id,a);for(JsonNode entity:analysis.path("entities"))if("PRODUCT".equalsIgnoreCase(entity.path("type").asText()))repository.linkProductIfKnown(event.id,entity.path("name").asText());Event refreshed=refresh(event.id);articles.updateStatus(articleId,ArticleStatus.PROCESSED);return refreshed;}catch(Exception e){articles.updateStatus(articleId,ArticleStatus.AI_FAILED);throw e;}}
    public Event reprocess(long id){return process(id,true);}
    @Transactional public Event refresh(long eventId){Event e=events.findById(eventId);AiRequest input=new AiRequest();JsonNode enriched=call("EVENT_ENRICHMENT",null,eventId,prompts.eventEnrichment(),eventJson(e));EventRequest r=new EventRequest();r.title=required(enriched,"title");r.summary=required(enriched,"summary");r.whatHappened=required(enriched,"whatHappened");r.whyImportant=required(enriched,"whyImportant");r.availability=required(enriched,"availability");r.developerImpact=required(enriched,"developerImpact");r.category=EventCategory.valueOf(required(enriched,"category"));r.eventTime=date(enriched.path("eventTime").asText(null),e.eventTime);r.impactScore=score(enriched,"impactScore");r.technicalScore=score(enriched,"technicalScore");r.availabilityScore=score(enriched,"availabilityScore");r.developerValueScore=score(enriched,"developerValueScore");r.credibilityScore=deterministicCredibility(e,score(enriched,"credibilityScore"));r.freshnessScore=score(enriched,"freshnessScore");r.totalScore=(int)Math.round(r.developerValueScore*dvW+r.impactScore*impactW+r.technicalScore*techW+r.availabilityScore*availabilityW+r.credibilityScore*credibilityW+r.freshnessScore*freshnessW);r.reviewStatus=ReviewStatus.PENDING;r.publishStatus=PublishStatus.DRAFT;return events.update(eventId,r);}
    private Event matchOrCreate(Article a,JsonNode analysis){List<Event> candidates=events.findRecent(LocalDateTime.now().minusDays(7));if(!candidates.isEmpty()){JsonNode match=call("EVENT_MATCHING",a.id,null,prompts.eventMatching(),analysis.toString()+"\nCandidates:"+eventCandidates(candidates));if(match.path("matched").asBoolean()&&match.path("confidence").asDouble()>=threshold){long id=match.path("eventId").asLong();if(candidates.stream().anyMatch(e->e.id==id))return events.findById(id);}}EventRequest r=new EventRequest();r.title=required(analysis,"eventCandidateTitle");r.summary=analysis.path("summary").asText();r.eventTime=date(analysis.path("eventTime").asText(null),a.publishedAt);r.reviewStatus=ReviewStatus.PENDING;r.publishStatus=PublishStatus.DRAFT;return events.create(r);}
    private void attach(long eventId,Article a){ArticleRelationRequest r=new ArticleRelationRequest();r.primarySource=Boolean.TRUE.equals(a.sourceOfficial);r.relationType=Boolean.TRUE.equals(r.primarySource)?ArticleRelationType.PRIMARY:ArticleRelationType.SUPPORTING;events.attachArticle(eventId,a.id,r);}
    private JsonNode call(String type,Long articleId,Long eventId,String system,String user){AiRequest r=new AiRequest();r.requestType=type;r.articleId=articleId;r.eventId=eventId;r.systemPrompt=system;r.userPrompt=user;Exception last=null;for(int i=0;i<2;i++)try{AiResponse response=ai.generate(r);JsonNode json=mapper.readTree(response.content);if(!json.isObject())throw new IllegalArgumentException("AI output must be JSON object");repository.log(r,response,"SUCCESS",null);return json;}catch(Exception e){last=e;}repository.log(r,null,"FAILED",last.getMessage());throw new IllegalStateException("AI returned invalid response after retry",last);}
    private void validateAnalysis(JsonNode n){if(!n.has("relevant")||!n.has("eventCandidateTitle")||!n.path("entities").isArray())throw new IllegalArgumentException("Invalid article analysis schema");}
    private String required(JsonNode n,String f){String v=n.path(f).asText(null);if(v==null||v.trim().isEmpty())throw new IllegalArgumentException("AI field missing: "+f);return v;}
    private int score(JsonNode n,String f){int v=n.path(f).asInt(-1);if(v<0||v>10)throw new IllegalArgumentException("Invalid score: "+f);return v;}
    private int deterministicCredibility(Event e,int aiScore){boolean primary=e.articles!=null&&e.articles.stream().anyMatch(a->Boolean.TRUE.equals(a.primarySource));int count=e.articles==null?0:e.articles.size();return Math.min(10,Math.max(aiScore,primary?9:count>1?7:5));}
    private LocalDateTime date(String v,LocalDateTime fallback){try{return v==null?fallback:OffsetDateTime.parse(v).toLocalDateTime();}catch(Exception x){try{return LocalDateTime.parse(v);}catch(Exception ignored){return fallback;}}}
    private String articleJson(Article a){try{return mapper.writeValueAsString(a);}catch(Exception e){throw new IllegalStateException(e);}}private String eventJson(Event e){try{return mapper.writeValueAsString(e);}catch(Exception x){throw new IllegalStateException(x);}}private String eventCandidates(List<Event> e){try{return mapper.writeValueAsString(e);}catch(Exception x){throw new IllegalStateException(x);}}
}
